$$
\begin{array}{r l} & {\frac {\partial z}{\partial \rho} = \frac {\partial z}{\partial x} \cdot \frac {\partial x}{\partial \rho} + \frac {\partial z}{\partial y} \cdot \frac {\partial y}{\partial \rho} = \left(\frac {\partial z}{\partial u} \cdot \frac {\partial u}{\partial x} + \frac {\partial z}{\partial v} \cdot \frac {\partial v}{\partial x}\right) \frac {\partial x}{\partial \rho} + \left(\frac {\partial z}{\partial u} \cdot \frac {\partial u}{\partial y} + \frac {\partial z}{\partial v} \cdot \frac {\partial v}{\partial y}\right) \frac {\partial y}{\partial \rho}} \\ & {\qquad = 2 (x \cos \varphi - y \sin \varphi) \frac {\partial z}{\partial u} - \sin x y \cdot (y \cos \varphi + x \sin \varphi) \frac {\partial z}{\partial v},} \\ & {\frac {\partial z}{\partial \varphi} = \frac {\partial z}{\partial x} \cdot \frac {\partial x}{\partial \varphi} + \frac {\partial z}{\partial y} \cdot \frac {\partial y}{\partial \varphi} = \left(\frac {\partial z}{\partial u} \cdot \frac {\partial u}{\partial x} + \frac {\partial z}{\partial v} \cdot \frac {\partial v}{\partial x}\right) \frac {\partial x}{\partial \varphi} + \left(\frac {\partial z}{\partial u} \cdot \frac {\partial u}{\partial y} + \frac {\partial z}{\partial v} \cdot \frac {\partial v}{\partial y}\right) \frac {\partial y}{\partial \varphi}} \\ & {\qquad = - 2 \rho (x \sin \varphi + y \cos \varphi) \frac {\partial z}{\partial u} + \rho \sin x y \cdot (y \sin \varphi - x \cos \varphi) \frac {\partial z}{\partial v}.} \end{array}
$$
